const Hypercore = require('hypercore')

async function main () {
  const writer = new Hypercore('./writer')
  await writer.ready()
  await writer.append(['block 0', 'block 1', 'block 2', 'block 3', 'block 4'])

  // The reader knows only the writer's public key
  const reader = new Hypercore('./reader', writer.key)
  await reader.ready()
  reader.on('download', (index) => console.log('downloaded block', index))

  // Wire the two together in-process. Over a network you would pipe sockets instead.
  const toReader = writer.replicate(true)
  const toWriter = reader.replicate(false)
  toReader.pipe(toWriter).pipe(toReader)

  const block = await reader.get(3) // waits for just this block
  console.log('reader got:', block.toString())
  console.log('reader has block 3?', await reader.has(3))
  console.log('reader has block 0?', await reader.has(0))
  console.log('reader length:', reader.length)

  toReader.destroy()
  toWriter.destroy()
  await writer.close()
  await reader.close()
}

main().catch(console.error)

const Hypercore = require('hypercore')

async function main () {
  const core = new Hypercore('./session-core')
  await core.ready()
  await core.append(['one', 'two', 'three'])

  const snap = core.snapshot()
  await snap.ready()
  await core.append('four')
  console.log('core length:', core.length, 'snapshot length:', snap.length)

  console.log('fork before:', core.fork)
  await core.truncate(2)
  console.log('length after truncate:', core.length, 'fork after:', core.fork)

  await snap.close()
  await core.close()
}

main().catch(console.error)

const Hypercore = require('hypercore')
const crypto = require('crypto')

async function main () {
  const key = crypto.randomBytes(32)
  const core = new Hypercore('./secret-core', { encryption: { key } })
  await core.ready()
  await core.append(Buffer.from('only readable with the key'))
  console.log((await core.get(0)).toString())
  await core.close()
}

